/* * @lc app=leetcode id=1293 lang=kotlin * * [1293] Shortest Path in a Grid with Obstacles Elimination */ class Solution { fun shortestPath(grid: Array<IntArray>, k: Int): Int = Array(grid.size) { IntArray(grid[0].size) { -1 } }.apply { this[0][0] = k }.let { vis -> ArrayDeque<IntArray>().apply { add(intArrayOf(0, 0, k, 0)) }.let { q -> generateSequence { if (q.isNotEmpty()) q.removeFirst() else null }.firstOrNull { node -> node[0] == grid.size - 1 && node[1] == grid[0].size - 1 || run { arrayOf(-1 to 0, 1 to 0, 0 to -1, 0 to 1).forEach { (dr, dc) -> (node[0] + dr to node[1] + dc).let { (nr, nc) -> if (nr in grid.indices && nc in grid[0].indices && node[2] - grid[nr][nc] > vis[nr][nc]) (node[2] - grid[nr][nc]).also { rem -> vis[nr][nc] = rem.also{q.add(intArrayOf(nr, nc, rem, node[3] + 1))} } else null } }.run{false} } }?.get(3) ?: -1 } } }